    _Spec(mode: StoryChallengeMode.storyCompletion, prompt: '小满问：“是不是先在祈年殿求丰收，然后去圜丘____？”', answer: '继续求丰收', sourceSentence: '小满问：“是不是先在祈年殿求丰收，然后去圜丘继续求丰收？”', options: <String>['继续求丰收','保存神牌','重新打板','提交校展'], rationales: <String>['正确：这正是粗剪制造的错误连续理解。','保存神牌与皇穹宇功能有关，不是小满的误解。','打板是拍摄动作，未出现在他的复述中。','提交校展是现代任务，不是历史内容。'], learning: '精确识别误解内容', knowledge: '祈谷被错误延伸到圜丘', language: '然后…继续…', reasoning: '从观众话语恢复错误关系', why: '小满把两个地点理解为一场持续的求丰收仪式。', difficulty: 'Lv6 直接转折证据', storyEvidence: '“然后去圜丘继续求丰收？”', knowledgeSource: _story),
    _Spec(mode: StoryChallengeMode.storyCompletion, prompt: '林桥承认：“不是你嫌我剪得太快，是他真的____。”', answer: '看成了一场', sourceSentence: '林桥承认：“不是你嫌我剪得太快，是他真的看成了一场。”', options: <String>['看成了一场','忘了祈年殿','不喜欢画面','错过了截止'], rationales: <String>['正确：她明确承认误解已由观众发生。','小满没有忘记祈年殿，反而把它和圜丘连起来。','问题是历史关系，不是审美喜好。','截止是创作者约束，不是观众反应。'], learning: '补全人物态度转变句', knowledge: '外部反馈验证误导', language: '不是…是…', reasoning: '从对比结构识别真正原因', why: '“看成了一场”取代了她之前对何予“太较真”的解释。', difficulty: 'Lv6 立场变化', storyEvidence: '“是他真的看成了一场。”', knowledgeSource: _story),
    _Spec(mode: StoryChallengeMode.storyEvidence, prompt: '为什么小满的语音比何予再次解释史实更能推动林桥？', answer: '它证明普通观众已经按粗剪线索形成了具体错误理解。', sourceSentence: '那句话几乎照抄了剪辑制造的顺序，却不是何予教给他的。', options: <String>['它证明普通观众已经按粗剪线索形成了具体错误理解。','小满比官方来源更权威。','小满知道更多天坛历史。','语音比文字天然更准确。'], rationales: <String>['正确：反馈验证的是传播效果，不是历史权威。','小满不是史实来源，官方来源仍负责历史事实。','故事没有说他掌握更多历史。','媒介形式不是可信度原因。'], learning: '区分历史事实证据与传播效果证据', knowledge: '两类证据的不同作用', language: '证明…形成…', reasoning: '判断证据与问题的匹配', why: '小满最能回答“观众会不会误解”这个问题。', difficulty: 'Lv6 证据类型', storyEvidence: '却不是何予教给他的。', knowledgeSource: _story),
    _Spec(mode: StoryChallengeMode.storyEvidence, prompt: '林桥为什么没有在听到语音后立刻删除？', answer: '她已经承认问题，但还没有找到既准确又能成立的叙事方案。', sourceSentence: '她没有立刻删，只低声说…', options: <String>['她已经承认问题，但还没有找到既准确又能成立的叙事方案。','她认为小满的误解完全没有价值。','她决定继续原剪法直到最后。','何予禁止她碰时间线。'], rationales: <String>['正确：Lv6 是认知转折，最终方案要到 Lv7 才出现。','她正是因为重视这条反馈才改变态度。','她没有承诺坚持旧剪法。','何予没有夺走她的编辑权限。'], learning: '理解转折与决定之间仍有距离', knowledge: '人物变化节奏', language: '已经…但还没有…', reasoning: '从事件位置推断未完成任务', why: 'Story 明确保留“没有立刻删”的犹豫。', difficulty: 'Lv6 叙事推断', storyEvidence: '她没有立刻删。', knowledgeSource: _story),
