StoryChallengeSet buildTempleOfHeavenChallenge({
  required int level,
  required List<String> storyParagraphs,
}) {
  final safeLevel = level.clamp(1, 10).toInt();
  final specs = templeOfHeavenChallengeMatrix[safeLevel - 1];
  if (specs.length != 12) {
    throw StateError('Temple Lv$safeLevel must contain exactly 12 questions.');
  }
  final activeStory = templeStoryParagraphsByLevel[safeLevel - 1];
  if (storyParagraphs.length != activeStory.length ||
      storyParagraphs.asMap().entries.any(
            (entry) => entry.value != activeStory[entry.key],
          )) {
    throw StateError(
      'Temple Lv$safeLevel Challenge received a different Story context.',
    );
  }
  final taughtStoryText = templeStoryParagraphsByLevel
      .take(safeLevel)
      .expand((paragraphs) => paragraphs)
      .join('\n');
  final questions = <StoryChallengeQuestion>[];
  for (var index = 0; index < specs.length; index += 1) {
    final spec = specs[index];
    _validateSpec(safeLevel, index, spec, taughtStoryText);
    final options = List<String>.unmodifiable(spec.options);
    questions.add(StoryChallengeQuestion(
      id: 'toh-lv$safeLevel-q${index + 1}-${spec.mode.name}',
      mode: spec.mode,
      sourceSentence: spec.sourceSentence,
      prompt: spec.prompt,
      answer: spec.answer,
      options: options,
      characterTiles: spec.mode == StoryChallengeMode.sentenceRebuild
          ? List<String>.unmodifiable(_scramble(spec.chunks, safeLevel, index))
          : const <String>[],
      errorSegments: List<String>.unmodifiable(spec.errorSegments),
      errorSegmentIndex: spec.errorIndex,
      grammarFamily: spec.grammarFamily,
      grammarWhyWrong: spec.mode == StoryChallengeMode.grammarRepair ? spec.why : null,
      grammarRevisionRule: spec.grammarRule,
      grammarOptionExplanations: spec.mode == StoryChallengeMode.grammarRepair
          ? List<String>.unmodifiable(spec.rationales)
          : const <String>[],
      narrationText: spec.prompt,
      learningObjective: spec.learning,
      knowledgeTarget: spec.knowledge,
      languageTarget: spec.language,
      reasoningTarget: spec.reasoning,
      whyCorrect: spec.why,
      distractorRationales: List<String>.unmodifiable(spec.rationales),
      difficulty: spec.difficulty,
      storyEvidence: spec.storyEvidence,
      knowledgeSource: spec.knowledgeSource,
      signature: QuestionDesignSignature(
        journeyId: templeOfHeavenJourneyId,
        sessionLevel: safeLevel,
        mode: spec.mode,
        sourceParagraphIndex: 0,
        sourceSentenceIndex: index,
        sourceHash: _hash(spec.sourceSentence),
        syntaxPattern: _syntax(spec.sourceSentence),
        operationType: _operation(spec.mode),
        errorFamily: spec.grammarFamily,
        gapType: spec.mode == StoryChallengeMode.storyCompletion ? 'context-completion' : null,
        answerShape: spec.mode == StoryChallengeMode.sentenceRebuild ? '${spec.chunks.length} semantic chunks' : '4-choice',
        distractorStrategy: spec.mode == StoryChallengeMode.sentenceRebuild ? 'semantic-order' : 'authored option-specific misconception',
        templateSignature: _hash('${spec.mode.name}|${_normalizedTemplate(spec.prompt)}'),
        semanticSignature: _hash('$safeLevel|${spec.mode.name}|${spec.learning}|${spec.knowledge}|${spec.reasoning}|${spec.answer}'),
      ),
    ));
  }
  return StoryChallengeSet(
    journeyId: templeOfHeavenJourneyId,
    sessionLevel: safeLevel,
    questions: List<StoryChallengeQuestion>.unmodifiable(questions),
  );
}

void _validateSpec(int level, int index, _Spec spec, String storyText) {
  final label = 'Temple Lv$level Q${index + 1}';
  if (spec.learning.trim().isEmpty || spec.knowledge.trim().isEmpty || spec.language.trim().isEmpty || spec.reasoning.trim().isEmpty || spec.why.trim().isEmpty || spec.difficulty.trim().isEmpty || spec.knowledgeSource.trim().isEmpty) {
    throw StateError('$label authoring record incomplete.');
  }
  if (spec.mode == StoryChallengeMode.sentenceRebuild) {
    if (spec.chunks.length < 3 || spec.chunks.join() != spec.answer || spec.chunks.any(_singleHanFragment)) {
      throw StateError('$label semantic rebuild invalid.');
    }
  } else {
    if (spec.options.length != 4 || spec.options.toSet().length != 4 || spec.options.where((item) => item == spec.answer).length != 1 || spec.rationales.length != 4 || spec.rationales.toSet().length != 4) {
      throw StateError('$label MCQ/options/rationales invalid.');
    }
  }
  if (spec.mode == StoryChallengeMode.grammarRepair) {
    if (spec.errorSegments.length != 4 || spec.errorIndex == null || spec.errorSegments.join() != spec.prompt || spec.errorSegments.any(_badGrammarSegment) || spec.options.any(_notCompleteSentence)) {
      throw StateError('$label Grammar Step 1/2 invalid.');
    }
  }
  if (spec.mode == StoryChallengeMode.storyCompletion) {
    if (!spec.prompt.contains('____') || spec.prompt.replaceFirst('____', spec.answer) != spec.sourceSentence) {
      throw StateError('$label Context Completion does not restore source.');
    }
  }
  if (spec.mode == StoryChallengeMode.storyEvidence) {
    final compactStory = storyText.replaceAll(RegExp(r'[“”"，。？！：；\s]'), '');
    final compactEvidence = spec.storyEvidence.replaceAll(RegExp(r'[“”"，。？！：；\s]'), '');
    final tokens = compactEvidence.split(RegExp(r'[，。？！：；]')).where((token) => token.length >= 4);
    if (compactEvidence.length >= 4 && !compactStory.contains(compactEvidence) && !tokens.any(compactStory.contains)) {
      // Story evidence may intentionally combine two exact fragments from the same level.
      final pieces = spec.storyEvidence.split(RegExp(r'[/…]')).map((item) => item.replaceAll(RegExp(r'[“”"，。？！：；\s]'), '')).where((item) => item.length >= 4);
      if (!pieces.any(compactStory.contains)) {
        throw StateError('$label evidence not grounded in current Story.');
      }
    }
  }
}

bool _badGrammarSegment(String value) {
  final text = value.trim();
  if (text.isEmpty || RegExp(r'^[。，“”！？：；、…]+$').hasMatch(text)) return true;
  final core = text.replaceAll(RegExp(r'[。，“”！？：；、…]+$'), '');
  return core.isEmpty || RegExp(r'^[的了在写往着过把被]+$').hasMatch(core);
}

bool _notCompleteSentence(String value) {
  final text = value.trim();
  return text.length < 6 || !RegExp(r'[。？！]$').hasMatch(text);
}

bool _singleHanFragment(String value) {
  final han = RegExp(r'[\u3400-\u9fff]').allMatches(value).length;
  return han == 1 && !const <String>{'却', '再'}.contains(value);
}

List<String> _scramble(List<String> chunks, int level, int index) {
  final result = List<String>.of(chunks.reversed);
  if (result.length > 2) {
    final shift = (level + index) % result.length;
    return <String>[...result.skip(shift), ...result.take(shift)];
  }
  return result;
}

String _operation(StoryChallengeMode mode) => switch (mode) {
  StoryChallengeMode.sentenceRebuild => 'Semantic Sentence Rebuild',
  StoryChallengeMode.grammarRepair => 'Grammar Repair',
  StoryChallengeMode.storyCompletion => 'Context Completion',
  StoryChallengeMode.storyEvidence => 'Story Evidence / Understanding',
  StoryChallengeMode.knowledgeReasoning => 'Beijing Knowledge / Spatial Reasoning',
  StoryChallengeMode.scenarioDecision => 'Scenario / Decision',
};

String _syntax(String value) {
  if (value.contains(RegExp(r'虽然|即使|如果'))) return '条件让步';
  if (value.contains(RegExp(r'因为|所以|因此'))) return '因果结构';
  if (value.contains('把')) return '把字句';
  if (value.contains(RegExp(r'却|但是|而'))) return '转折结构';
  if (value.contains('，')) return '复句';
  return '主谓宾';
}

String _normalizedTemplate(String value) => value
    .replaceAll(RegExp(r'林桥|何予|小满'), '<PERSON>')
    .replaceAll(RegExp(r'祈年殿|圜丘|皇穹宇|天坛'), '<PLACE>')
    .replaceAll(RegExp(r'\s+'), ' ')
    .trim();

String _hash(String value) {
  var hash = 0x811c9dc5;
  for (final unit in value.codeUnits) {
    hash = ((hash ^ unit) * 0x01000193) & 0xffffffff;
  }
  return hash.toRadixString(16).padLeft(8, '0');
}
